impl<'a, 'b> OperateCpi<'a, 'b> {
    pub fn new(
        program: &'b solana_account_info::AccountInfo<'a>,
        accounts: OperateCpiAccounts<'a, 'b>,
        args: OperateInstructionArgs,
    ) -> Self {
        Self {
            __program: program,
            signer: accounts.signer,
            signer_supply_token_account: accounts.signer_supply_token_account,
            signer_borrow_token_account: accounts.signer_borrow_token_account,
            recipient: accounts.recipient,
            recipient_borrow_token_account: accounts.recipient_borrow_token_account,
            recipient_supply_token_account: accounts.recipient_supply_token_account,
            vault_config: accounts.vault_config,
            vault_state: accounts.vault_state,
            supply_token: accounts.supply_token,
            borrow_token: accounts.borrow_token,
            oracle: accounts.oracle,
            position: accounts.position,
            position_token_account: accounts.position_token_account,
            current_position_tick: accounts.current_position_tick,
            final_position_tick: accounts.final_position_tick,
            current_position_tick_id: accounts.current_position_tick_id,
            final_position_tick_id: accounts.final_position_tick_id,
            new_branch: accounts.new_branch,
            supply_token_reserves_liquidity: accounts.supply_token_reserves_liquidity,
            borrow_token_reserves_liquidity: accounts.borrow_token_reserves_liquidity,
            vault_supply_position_on_liquidity: accounts.vault_supply_position_on_liquidity,
            vault_borrow_position_on_liquidity: accounts.vault_borrow_position_on_liquidity,
            supply_rate_model: accounts.supply_rate_model,
            borrow_rate_model: accounts.borrow_rate_model,
            vault_supply_token_account: accounts.vault_supply_token_account,
            vault_borrow_token_account: accounts.vault_borrow_token_account,
            supply_token_claim_account: accounts.supply_token_claim_account,
            borrow_token_claim_account: accounts.borrow_token_claim_account,
            liquidity: accounts.liquidity,
            liquidity_program: accounts.liquidity_program,
            oracle_program: accounts.oracle_program,
            supply_token_program: accounts.supply_token_program,
            borrow_token_program: accounts.borrow_token_program,
            associated_token_program: accounts.associated_token_program,
            system_program: accounts.system_program,
            __args: args,
        }
    }
    #[inline(always)]
    pub fn invoke(&self) -> solana_program_error::ProgramResult {
        self.invoke_signed_with_remaining_accounts(&[], &[])
    }
    #[inline(always)]
    pub fn invoke_with_remaining_accounts(
        &self,
        remaining_accounts: &[(&'b solana_account_info::AccountInfo<'a>, bool, bool)],
    ) -> solana_program_error::ProgramResult {
        self.invoke_signed_with_remaining_accounts(&[], remaining_accounts)
    }
    #[inline(always)]
    pub fn invoke_signed(&self, signers_seeds: &[&[&[u8]]]) -> solana_program_error::ProgramResult {
        self.invoke_signed_with_remaining_accounts(signers_seeds, &[])
    }
    #[allow(clippy::arithmetic_side_effects)]
    #[allow(clippy::clone_on_copy)]
    #[allow(clippy::vec_init_then_push)]
    pub fn invoke_signed_with_remaining_accounts(
        &self,
        signers_seeds: &[&[&[u8]]],
        remaining_accounts: &[(&'b solana_account_info::AccountInfo<'a>, bool, bool)],
    ) -> solana_program_error::ProgramResult {
        let mut accounts = Vec::with_capacity(35 + remaining_accounts.len());
        accounts.push(solana_instruction::AccountMeta::new(*self.signer.key, true));
        if let Some(signer_supply_token_account) = self.signer_supply_token_account {
            accounts.push(solana_instruction::AccountMeta::new(
                *signer_supply_token_account.key,
                false,
            ));
        } else {
            accounts.push(solana_instruction::AccountMeta::new_readonly(
                crate::LEND_BORROW_ID,
                false,
            ));
        }
        if let Some(signer_borrow_token_account) = self.signer_borrow_token_account {
            accounts.push(solana_instruction::AccountMeta::new(
                *signer_borrow_token_account.key,
                false,
            ));
        } else {
            accounts.push(solana_instruction::AccountMeta::new_readonly(
                crate::LEND_BORROW_ID,
                false,
            ));
        }
        if let Some(recipient) = self.recipient {
            accounts.push(solana_instruction::AccountMeta::new_readonly(
                *recipient.key,
                false,
            ));
        } else {
            accounts.push(solana_instruction::AccountMeta::new_readonly(
                crate::LEND_BORROW_ID,
                false,
            ));
        }
        if let Some(recipient_borrow_token_account) = self.recipient_borrow_token_account {
            accounts.push(solana_instruction::AccountMeta::new(
                *recipient_borrow_token_account.key,
                false,
            ));
        } else {
            accounts.push(solana_instruction::AccountMeta::new_readonly(
                crate::LEND_BORROW_ID,
                false,
            ));
        }
        if let Some(recipient_supply_token_account) = self.recipient_supply_token_account {
            accounts.push(solana_instruction::AccountMeta::new(
                *recipient_supply_token_account.key,
                false,
            ));
        } else {
            accounts.push(solana_instruction::AccountMeta::new_readonly(
                crate::LEND_BORROW_ID,
                false,
            ));
        }
        accounts.push(solana_instruction::AccountMeta::new_readonly(
            *self.vault_config.key,
            false,
        ));
        accounts.push(solana_instruction::AccountMeta::new(
            *self.vault_state.key,
            false,
        ));
        accounts.push(solana_instruction::AccountMeta::new_readonly(
            *self.supply_token.key,
            false,
        ));
        accounts.push(solana_instruction::AccountMeta::new_readonly(
            *self.borrow_token.key,
            false,
        ));
        accounts.push(solana_instruction::AccountMeta::new_readonly(
            *self.oracle.key,
            false,
        ));
        accounts.push(solana_instruction::AccountMeta::new(
            *self.position.key,
            false,
        ));
        accounts.push(solana_instruction::AccountMeta::new_readonly(
            *self.position_token_account.key,
            false,
        ));
        accounts.push(solana_instruction::AccountMeta::new(
            *self.current_position_tick.key,
            false,
        ));
        accounts.push(solana_instruction::AccountMeta::new(
            *self.final_position_tick.key,
            false,
        ));
        accounts.push(solana_instruction::AccountMeta::new_readonly(
            *self.current_position_tick_id.key,
            false,
        ));
        accounts.push(solana_instruction::AccountMeta::new(
            *self.final_position_tick_id.key,
            false,
        ));
        accounts.push(solana_instruction::AccountMeta::new(
            *self.new_branch.key,
            false,
        ));
        accounts.push(solana_instruction::AccountMeta::new(
            *self.supply_token_reserves_liquidity.key,
            false,
        ));
        accounts.push(solana_instruction::AccountMeta::new(
            *self.borrow_token_reserves_liquidity.key,
            false,
        ));
        accounts.push(solana_instruction::AccountMeta::new(
            *self.vault_supply_position_on_liquidity.key,
            false,
        ));
        accounts.push(solana_instruction::AccountMeta::new(
            *self.vault_borrow_position_on_liquidity.key,
            false,
        ));
        accounts.push(solana_instruction::AccountMeta::new_readonly(
            *self.supply_rate_model.key,
            false,
        ));
        accounts.push(solana_instruction::AccountMeta::new_readonly(
            *self.borrow_rate_model.key,
            false,
        ));
        accounts.push(solana_instruction::AccountMeta::new(
            *self.vault_supply_token_account.key,
            false,
        ));
        accounts.push(solana_instruction::AccountMeta::new(
            *self.vault_borrow_token_account.key,
            false,
        ));
        if let Some(supply_token_claim_account) = self.supply_token_claim_account {
            accounts.push(solana_instruction::AccountMeta::new(
                *supply_token_claim_account.key,
                false,
            ));
        } else {
            accounts.push(solana_instruction::AccountMeta::new_readonly(
                crate::LEND_BORROW_ID,
                false,
            ));
        }
        if let Some(borrow_token_claim_account) = self.borrow_token_claim_account {
            accounts.push(solana_instruction::AccountMeta::new(
                *borrow_token_claim_account.key,
                false,
            ));
        } else {
            accounts.push(solana_instruction::AccountMeta::new_readonly(
                crate::LEND_BORROW_ID,
                false,
            ));
        }
        accounts.push(solana_instruction::AccountMeta::new_readonly(
            *self.liquidity.key,
            false,
        ));
        accounts.push(solana_instruction::AccountMeta::new_readonly(
            *self.liquidity_program.key,
            false,
        ));
        accounts.push(solana_instruction::AccountMeta::new_readonly(
            *self.oracle_program.key,
            false,
        ));
        accounts.push(solana_instruction::AccountMeta::new_readonly(
            *self.supply_token_program.key,
            false,
        ));
        accounts.push(solana_instruction::AccountMeta::new_readonly(
            *self.borrow_token_program.key,
            false,
        ));
        if let Some(associated_token_program) = self.associated_token_program {
            accounts.push(solana_instruction::AccountMeta::new_readonly(
                *associated_token_program.key,
                false,
            ));
        } else {
            accounts.push(solana_instruction::AccountMeta::new_readonly(
                crate::LEND_BORROW_ID,
                false,
            ));
        }
        accounts.push(solana_instruction::AccountMeta::new_readonly(
            *self.system_program.key,
            false,
        ));
        remaining_accounts.iter().for_each(|remaining_account| {
            accounts.push(solana_instruction::AccountMeta {
                pubkey: *remaining_account.0.key,
                is_writable: remaining_account.1,
                is_signer: remaining_account.2,
            })
        });
        let mut data = OperateInstructionData::new().try_to_vec().unwrap();
        let mut args = self.__args.try_to_vec().unwrap();
        data.append(&mut args);

        let instruction = solana_instruction::Instruction {
            program_id: crate::LEND_BORROW_ID,
            accounts,
            data,
        };
        let mut account_infos = Vec::with_capacity(36 + remaining_accounts.len());
        account_infos.push(self.__program.clone());
        account_infos.push(self.signer.clone());
        if let Some(signer_supply_token_account) = self.signer_supply_token_account {
            account_infos.push(signer_supply_token_account.clone());
        }
        if let Some(signer_borrow_token_account) = self.signer_borrow_token_account {
            account_infos.push(signer_borrow_token_account.clone());
        }
        if let Some(recipient) = self.recipient {
            account_infos.push(recipient.clone());
        }
        if let Some(recipient_borrow_token_account) = self.recipient_borrow_token_account {
            account_infos.push(recipient_borrow_token_account.clone());
        }
        if let Some(recipient_supply_token_account) = self.recipient_supply_token_account {
            account_infos.push(recipient_supply_token_account.clone());
        }
        account_infos.push(self.vault_config.clone());
        account_infos.push(self.vault_state.clone());
        account_infos.push(self.supply_token.clone());
        account_infos.push(self.borrow_token.clone());
        account_infos.push(self.oracle.clone());
        account_infos.push(self.position.clone());
        account_infos.push(self.position_token_account.clone());
        account_infos.push(self.current_position_tick.clone());
        account_infos.push(self.final_position_tick.clone());
        account_infos.push(self.current_position_tick_id.clone());
        account_infos.push(self.final_position_tick_id.clone());
        account_infos.push(self.new_branch.clone());
        account_infos.push(self.supply_token_reserves_liquidity.clone());
        account_infos.push(self.borrow_token_reserves_liquidity.clone());
        account_infos.push(self.vault_supply_position_on_liquidity.clone());
        account_infos.push(self.vault_borrow_position_on_liquidity.clone());
        account_infos.push(self.supply_rate_model.clone());
        account_infos.push(self.borrow_rate_model.clone());
        account_infos.push(self.vault_supply_token_account.clone());
        account_infos.push(self.vault_borrow_token_account.clone());
        if let Some(supply_token_claim_account) = self.supply_token_claim_account {
            account_infos.push(supply_token_claim_account.clone());
        }
        if let Some(borrow_token_claim_account) = self.borrow_token_claim_account {
            account_infos.push(borrow_token_claim_account.clone());
        }
        account_infos.push(self.liquidity.clone());
        account_infos.push(self.liquidity_program.clone());
        account_infos.push(self.oracle_program.clone());
        account_infos.push(self.supply_token_program.clone());
        account_infos.push(self.borrow_token_program.clone());
        if let Some(associated_token_program) = self.associated_token_program {
            account_infos.push(associated_token_program.clone());
        }
        account_infos.push(self.system_program.clone());
        remaining_accounts
            .iter()
            .for_each(|remaining_account| account_infos.push(remaining_account.0.clone()));

        if signers_seeds.is_empty() {
            solana_cpi::invoke(&instruction, &account_infos)
        } else {
            solana_cpi::invoke_signed(&instruction, &account_infos, signers_seeds)
        }
    }
}

/// Instruction builder for `Operate` via CPI.
///
/// ### Accounts:
///
///   0. `[writable, signer]` signer
///   1. `[writable, optional]` signer_supply_token_account
///   2. `[writable, optional]` signer_borrow_token_account
///   3. `[optional]` recipient
///   4. `[writable, optional]` recipient_borrow_token_account
///   5. `[writable, optional]` recipient_supply_token_account
///   6. `[]` vault_config
